/**
 * Trusted-caller token for outbound peer calls.
 *
 * Acquires and caches (until shortly before expiry) this service's own trusted-caller
 * token for the system's trusted-caller audience, so every outbound cross-service `uses`
 * request can attach it as `X-CruftFree-Caller-Token`.
 * The token is a web identity token the platform's security token service signs for the
 * service's own role, with the audience as its `aud` claim.
 *
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 */
import { Logger } from '@nestjs/common';
import { GetWebIdentityTokenCommand, STSClient } from '@aws-sdk/client-sts';
import { REGION } from "../config/_bootstrap";
import { awsClient } from "../_runtime/aws-role";
import { deployTimeSetting } from "../config/settings";

/** The lifetime requested for each token (the platform grant caps it at this value). */
const TOKEN_LIFETIME_SECONDS = 300;
/** Renew a token once less than this much of its lifetime is left. */
const EXPIRY_SKEW_MS = 60000;
const SIGNING_ALGORITHM = "RS256";

let stsClient: STSClient | undefined;

interface CachedToken {
  readonly token: string;
  readonly expiresAtMs: number;
}

let cached: CachedToken | undefined;
let inFlight: Promise<CachedToken> | undefined;

// The longest acquiring the token may take. It is bounded on its own: never charged
// against an outbound call's timeout, and never left unbounded.
const CREDENTIAL_ACQUIRE_TIMEOUT_MS = 15000;
const callerTokenLogger = new Logger('CallerToken');

/** The trusted-caller token was not obtained within its bound. */
export class CallerTokenTimeoutError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CallerTokenTimeoutError';
  }
}

async function mint(audience: string): Promise<CachedToken> {
  if (!REGION) {
    throw new Error(
      'The trusted-caller token minter needs a region: the security token service has no ' +
        'global endpoint for web identity tokens. Generate with a resolved deployment region.',
    );
  }
  stsClient ??= awsClient(STSClient, { region: REGION });
  const response = await stsClient.send(
    new GetWebIdentityTokenCommand({
      Audience: [audience],
      SigningAlgorithm: SIGNING_ALGORITHM,
      DurationSeconds: TOKEN_LIFETIME_SECONDS,
    }),
  );
  if (response.WebIdentityToken === undefined || response.Expiration === undefined) {
    throw new Error(
      'The security token service returned no web identity token. Expected WebIdentityToken ' +
        'and Expiration; check the role is granted sts:GetWebIdentityToken for the audience.',
    );
  }
  return { token: response.WebIdentityToken, expiresAtMs: response.Expiration.getTime() };
}

/**
 * Return a cached-until-expiry trusted-caller token for the audience.
 *
 * The value is the BARE JWT for the `X-CruftFree-Caller-Token` header -- never prefixed
 * with `Bearer `: that header is a custom header, not `Authorization`, and a prefixed
 * value makes every consumer's JWT library fail to decode it.
 */
export async function acquireCallerToken(): Promise<string> {
  if (cached !== undefined && Date.now() < cached.expiresAtMs - EXPIRY_SKEW_MS) {
    return cached.token;
  }
  inFlight ??= mint(deployTimeSetting("CRUFTFREE_CALLER_AUDIENCE")).finally(() => {
    inFlight = undefined;
  });
  const minting = inFlight;
  let timedOut = false;
  let timer: ReturnType<typeof setTimeout> | undefined;
  const deadline = new Promise<never>((_resolve, reject) => {
    timer = setTimeout(() => {
      timedOut = true;
      reject(
        new CallerTokenTimeoutError(
          `The trusted-caller token was not obtained within ${CREDENTIAL_ACQUIRE_TIMEOUT_MS}ms. ` +
            'Expected the platform token endpoint to answer; check its reachability from this service.',
        ),
      );
    }, CREDENTIAL_ACQUIRE_TIMEOUT_MS);
  });
  // A mint that fails after the bound already failed the call: it is recorded, never
  // left as an unhandled rejection.
  minting.catch((err: unknown) => {
    if (timedOut) {
      callerTokenLogger.warn(
        `caller_token_failed_after_bound error_type=${err instanceof Error ? err.name : typeof err}`,
      );
    }
  });
  try {
    cached = await Promise.race([minting, deadline]);
  } finally {
    clearTimeout(timer);
  }
  return cached.token;
}
